<?php
namespace App\Http\Controllers;
use App\Models\{Reservation,RoomType,Room,Setting,RestaurantOrder,Payment};
use App\Services\{HotelService as Hotel,RecommendedBooking,TrainingPolicy,PaymentPosting,ConfirmationService};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class RecommendationsController extends Controller {
 public function reverseCharge(Request $q,Reservation $reservation,\App\Models\FolioCharge $charge){
  $v=$q->validate(['reason'=>'required|string|max:500']);return DB::transaction(function()use($reservation,$charge,$v){
   $r=Reservation::lockForUpdate()->findOrFail($reservation->id);\App\Services\BusinessDate::assertNoCheckout($r->id);abort_unless($charge->reservation_id===$r->id,404);if($r->status!=='Checked-in'||$charge->amount<=0||$charge->reversal_of)Hotel::fail('Only a positive charge on an active stay can be reversed.');$existing=$r->charges()->where('reversal_of',$charge->id)->first();if($existing)return $existing;
   $c=$r->charges()->create(['description'=>'Reversal of #'.$charge->id.': '.$v['reason'],'amount'=>-$charge->amount,'reversal_of'=>$charge->id]);Hotel::audit('charge.reversed',$r->code,['original_charge'=>$charge->id,'reversal'=>$c->id,'reason'=>$v['reason']]);return $c;
  });
 }
 public function quote(Request $q){$v=$q->validate(['guest_id'=>'sometimes|exists:guests,id','room_type_id'=>'required|exists:room_types,id','arrival'=>'required|date|after_or_equal:today','departure'=>'required|date|after:arrival','adults'=>'required|integer|min:1|max:20','children'=>'required|integer|min:0|max:20','requires_accessible_room'=>'sometimes|boolean','breakfast'=>'required|in:None,Buffet','breakfast_pax'=>'required|integer|min:0|max:40','promo_code'=>'nullable|string|max:40','discount_category'=>'sometimes|in:None,Senior,PWD','discount_verification'=>'nullable|string|max:500']);if(($v['discount_category']??'None')!=='None'){abort_unless(in_array($q->user()?->role,['admin','frontdesk']),403);if(empty($v['discount_verification']))Hotel::fail('Record a staff eligibility review for the discount.');}if(!in_array($q->user()?->role,['admin','frontdesk']))unset($v['guest_id']);$n=(int)\Carbon\Carbon::parse($v['arrival'])->diffInDays($v['departure']);if($n>90)Hotel::fail('Maximum stay is 90 nights.');return TrainingPolicy::quote(RoomType::findOrFail($v['room_type_id']),$v,$n);}
 public function policy(Request $q){
  if($q->isMethod('post')){
   abort_unless($q->user()->role==='admin',403);
   $v=$q->validate(['breakfast_buffet_rate'=>'required|numeric|min:0|max:100000','breakfast_plated_rate'=>'sometimes|numeric|min:0|max:100000','deposit_percent'=>'required|numeric|min:1|max:90','advance_discount_percent'=>'required|numeric|min:0|max:50','senior_discount_percent'=>'required|numeric|min:0|max:100','pwd_discount_percent'=>'required|numeric|min:0|max:100','local_tax_percent'=>'required|numeric|min:0|max:100','parking_spaces'=>'required|integer|min:0|max:10000','outside_food_allowed'=>'required|boolean','confirmation_reminders'=>'required|string|max:2000','promos'=>'present|array|max:50','promos.*.code'=>'required|string|distinct|max:40','promos.*.percent'=>'required|numeric|min:0|max:100','promos.*.start'=>'required|date','promos.*.end'=>'required|date|after_or_equal:promos.*.start','promos.*.public'=>'required|boolean','promos.*.label'=>'required|string|max:100','promos.*.first_time_only'=>'sometimes|boolean','promos.*.single_use'=>'sometimes|boolean','promos.*.guest_id'=>'sometimes|nullable|exists:guests,id','promos.*.issued_by'=>'sometimes|integer','promos.*.reason'=>'sometimes|string|max:200','advance_min_days'=>'sometimes|integer|min:1|max:90','require_bill_acknowledgment'=>'sometimes|boolean','buffet_inclusions'=>'sometimes|array|max:30','buffet_inclusions.*'=>'string|max:150']);
   $v=array_replace(TrainingPolicy::get(),$v);Setting::updateOrCreate(['key'=>'training_policy'],['value'=>$v]);Hotel::audit('policy.updated','training_policy');
  }return TrainingPolicy::get();
 }
 public function publicPolicy(){ $p=TrainingPolicy::get();$p['promos']=array_values(array_filter($p['promos'],fn($x)=>$x['public']&&$x['start']<=today()->toDateString()&&$x['end']>=today()->toDateString()));return $p;}
 public function available(Request $q){$v=$q->validate(['arrival'=>'required|date|after_or_equal:today','departure'=>'required|date|after:arrival|before_or_equal:'.today()->addYears(2)->toDateString(),'adults'=>'required|integer|min:1|max:20','children'=>'required|integer|min:0|max:20']);abort_if(\Carbon\Carbon::parse($v['arrival'])->diffInDays($v['departure'])>90,422,'Maximum training stay is 90 nights.');return RoomType::get()->filter(fn($t)=>$v['adults']+$v['children']<=$t->capacity+$t->extra_capacity&&RecommendedBooking::available($t,$v['arrival'],$v['departure']))->values();}
 public function book(Request $q){abort_unless(in_array($q->user()->role,['guest','admin','frontdesk']),403);$v=$q->validate(['room_type_id'=>'required|exists:room_types,id','arrival'=>'required|date|after_or_equal:today','departure'=>'required|date|after:arrival','adults'=>'required|integer|min:1|max:20','children'=>'required|integer|min:0|max:20','requires_accessible_room'=>'sometimes|boolean','breakfast'=>'required|in:None,Buffet','breakfast_pax'=>'required|integer|min:0|max:40','guest_id'=>'sometimes|exists:guests,id','payer_guest_id'=>'sometimes|exists:guests,id','occupant_ids'=>'sometimes|array|min:1','occupant_ids.*'=>'exists:guests,id','requests'=>'nullable|string|max:2000','source'=>'sometimes|in:Online,Telephone,Walk-in','promo_code'=>'nullable|string|max:40','company_name'=>'nullable|string|max:180','discount_category'=>'sometimes|in:None,Senior,PWD','discount_verification'=>'nullable|string|max:500']);if(\Carbon\Carbon::parse($v['arrival'])->diffInDays($v['departure'])>90)Hotel::fail('Maximum training stay is 90 nights.');$staff=$q->user()->role!=='guest';if($staff&&empty($v['guest_id']))Hotel::fail('Select the booking contact.');return response()->json(RecommendedBooking::create($v,$staff?$v['guest_id']:$q->user()->guest_id,$staff),201);}
 public function assign(Request $q,Reservation $reservation){$v=$q->validate(['room_id'=>'required|exists:rooms,id']);return RecommendedBooking::assign($reservation,$v['room_id']);}
 public function dates(Request $q,Reservation $reservation){\App\Services\BusinessDate::assertNoCheckout($reservation->id);abort_unless(in_array($q->user()->role,['admin','frontdesk'])||($q->user()->role==='guest'&&$q->user()->guest_id===$reservation->guest_id),403);$v=$q->validate(['arrival'=>'required|date|after:today','departure'=>'required|date|after:arrival']);return DB::transaction(function()use($reservation,$v){$type=RoomType::lockForUpdate()->findOrFail($reservation->room_type_id);$r=Reservation::lockForUpdate()->findOrFail($reservation->id);if($r->status!=='Confirmed'||$r->arrival<=today()->toDateString())Hotel::fail('Only future confirmed reservations can change dates.');if(\Carbon\Carbon::parse($v['arrival'])->diffInDays($v['departure'])>90)Hotel::fail('Maximum stay is 90 nights.');if(!RecommendedBooking::available($type,$v['arrival'],$v['departure'],$r->id)||($r->requires_accessible_room&&!RecommendedBooking::available($type,$v['arrival'],$v['departure'],$r->id,true)))Hotel::fail('Required room inventory is unavailable.');$old=(int)\Carbon\Carbon::parse($r->arrival)->diffInDays($r->departure);$new=(int)\Carbon\Carbon::parse($v['arrival'])->diffInDays($v['departure']);$pricing=$r->pricing;if($pricing){foreach(['room','extra_guests','breakfast','services_total','discount','local_tax','total','deposit_due','advance_payment_due','advance_discount_awarded'] as $k)$pricing[$k]=round(($pricing[$k]??0)/$old*$new,2);}if($pricing){$services=$pricing['services']??[];foreach($services as &$service){$service['amount']=round($service['amount']/$old*$new,2);$service['nights']=$new;}unset($service);$pricing['services']=$services;}if($pricing&&empty($pricing['advance_discount_awarded'])&&$v['arrival']<today()->addDays((int)($pricing['advance_min_days']??7))->toDateString()){$pricing['advance_discount_percent']=0;$pricing['advance_payment_due']=$pricing['total'];}$r->update([...$v,'room_id'=>null,'amount'=>round($r->amount/$old*$new,2),'pricing'=>$pricing]);Hotel::audit('reservation.dates-changed',$r->code);ConfirmationService::prepare($r);return $r;});}
 public function letters(Request $q,Reservation $reservation){abort_unless(in_array($q->user()->role,['admin','frontdesk'])||($q->user()->role==='guest'&&$q->user()->guest_id===$reservation->guest_id),403);return DB::table('confirmation_letters')->where('reservation_id',$reservation->id)->get();}
 public function batch(Request $q){$v=$q->validate(['allocations'=>'required|array|min:1|max:20','allocations.*.reservation_id'=>'required|distinct|exists:reservations,id','allocations.*.amount'=>'required|numeric|min:0.01|max:9999999','reference'=>'required|uuid','posting_location'=>'required|string|max:100']);return DB::transaction(function()use($q,$v){$existing=Payment::where('batch_reference',$v['reference'])->get();if($existing->isNotEmpty()){foreach($v['allocations'] as $a)abort_unless($existing->contains(fn($p)=>$p->reservation_id==(int)$a['reservation_id']&&(float)$p->amount==round($a['amount'],2)),409);abort_unless($existing->count()===count($v['allocations']),409);return ['reference'=>$v['reference'],'status'=>'Recorded'];}foreach($v['allocations'] as $a)\App\Services\BusinessDate::assertNoCheckout((int)$a['reservation_id']);$rows=PaymentPosting::lockAllocations($v['allocations']);PaymentPosting::post($rows,'Cash',$v['reference'],$q->user()->id,$v['posting_location']);return ['reference'=>$v['reference'],'status'=>'Recorded'];});}
 public function transfer(Request $q){$v=$q->validate(['from'=>'required|exists:reservations,id','to'=>'required|different:from|exists:reservations,id','amount'=>'required|numeric|min:0.01|max:9999999','reason'=>'required|string|max:500','reference'=>'required|uuid']);return DB::transaction(function()use($q,$v){$rs=Reservation::whereIn('id',[$v['from'],$v['to']])->orderBy('id')->lockForUpdate()->get()->keyBy('id');$from=$rs[$v['from']];$to=$rs[$v['to']];\App\Services\BusinessDate::assertNoCheckout($from->id);\App\Services\BusinessDate::assertNoCheckout($to->id);$prior=Payment::where('batch_reference',$v['reference'])->get();if($prior->isNotEmpty()){abort_unless($prior->count()===2&&$prior->contains(fn($p)=>$p->reservation_id==$from->id&&$p->kind==='Transfer Out'&&(float)$p->amount==round($v['amount'],2))&&$prior->contains(fn($p)=>$p->reservation_id==$to->id&&$p->kind==='Transfer In'&&(float)$p->amount==round($v['amount'],2)),409);return ['status'=>'Transferred'];}if($from->payer_guest_id!==$to->payer_guest_id||!in_array($from->status,['Confirmed','Cancelled'])||!in_array($to->status,['Confirmed','Checked-in']))Hotel::fail('Transfer only unused deposits or cancellation credits between eligible folios with the same payer.');$f=Hotel::folio($from);$available=$from->status==='Cancelled'?max(0,-$f['balance']):max(0,$f['paid']);if($v['amount']>$available||$v['amount']>Hotel::folio($to)['balance'])Hotel::fail('Amount exceeds transferable funds or destination balance.');foreach([[$from,'Transfer Out'],[$to,'Transfer In']] as [$r,$kind])Payment::create(['reservation_id'=>$r->id,'amount'=>$v['amount'],'method'=>'Internal transfer','kind'=>$kind,'idempotency_key'=>$v['reference'].'-'.$r->id,'batch_reference'=>$v['reference'],'receipt'=>'TRF-'.strtoupper(bin2hex(random_bytes(6))),'created_by'=>$q->user()->id]);Hotel::audit('deposit.transferred',$v['reference'],$v);return ['status'=>'Transferred'];});}
 public function updateOrder(Request $q,RestaurantOrder $order){\App\Services\BusinessDate::assertNoOrderCheckout($order->id);$v=$q->validate(['items'=>'required|array|min:1','items.*.menu_item_id'=>'required|exists:menu_items,id','items.*.quantity'=>'required|integer|min:1|max:100','reason'=>'required|string|max:500']);return DB::transaction(function()use($order,$v){$o=RestaurantOrder::lockForUpdate()->findOrFail($order->id);if($o->status!=='Open')Hotel::fail('Only unpaid, unposted orders may be edited.');$total=0;$lines=[];foreach($v['items'] as $i){$m=\App\Models\MenuItem::findOrFail($i['menu_item_id']);if(!$m->available)Hotel::fail('Item unavailable.');$total+=TrainingPolicy::cents($m->price)*$i['quantity'];$lines[]=['menu_item_id'=>$m->id,'name'=>$m->name,'quantity'=>$i['quantity'],'unit_price'=>$m->price];}Hotel::audit('order.edited',$o->code,['previous_items'=>$o->items->toArray(),'reason'=>$v['reason']]);$o->items()->delete();$o->items()->createMany($lines);$pricing=TrainingPolicy::restaurantPrice($total/100,$o->discount_category,$o->discount_verification);$o->update(['amount'=>$pricing['total'],'pricing'=>$pricing]);return $o->load('items');});}
 public function voidOrder(Request $q,RestaurantOrder $order){\App\Services\BusinessDate::assertNoOrderCheckout($order->id);$v=$q->validate(['reason'=>'required|string|max:500']);return DB::transaction(function()use($order,$v){$o=RestaurantOrder::lockForUpdate()->findOrFail($order->id);if($o->status!=='Open')Hotel::fail('Posted orders require a linked financial correction, not editing or voiding.');$o->update(['status'=>'Void']);if($o->dining_table_id)\App\Models\DiningTable::whereKey($o->dining_table_id)->update(['status'=>'Available']);Hotel::audit('order.voided',$o->code,$v);return $o;});}
 public function delivery(Request $q,RestaurantOrder $order){$v=$q->validate(['service_status'=>'required|in:Recorded,Out for delivery,Delivered','delivery_notes'=>'nullable|string|max:500']);$order->update($v);Hotel::audit('order.delivery',$order->code,$v);return $order;}
 public function requests(Request $q){$role=$q->user()->role;$department=$role==='restaurant'?'Restaurant':'Hotel';if($q->isMethod('post')){$v=$q->validate(['department'=>'required|in:Hotel,Restaurant','message'=>'required|string|max:2000']);abort_unless($role==='guest',403);$id=DB::table('service_requests')->insertGetId([...$v,'guest_id'=>$q->user()->guest_id,'created_at'=>now(),'updated_at'=>now()]);return ['id'=>$id];}return DB::table('service_requests')->when($role==='guest',fn($b)=>$b->where('guest_id',$q->user()->guest_id))->when(!in_array($role,['guest','admin']),fn($b)=>$b->where('department',$department))->orderByDesc('id')->get();}
 public function resolve(Request $q,int $id){$v=$q->validate(['status'=>'required|in:In progress,Resolved,Closed','resolution'=>'required|string|max:2000']);$row=DB::table('service_requests')->where('id',$id)->first();abort_unless($row,404);abort_unless($q->user()->role==='admin'||($row->department==='Hotel'&&in_array($q->user()->role,['frontdesk','housekeeping']))||($row->department==='Restaurant'&&$q->user()->role==='restaurant'),403);DB::table('service_requests')->where('id',$id)->update([...$v,'updated_at'=>now()]);Hotel::audit('request.updated',(string)$id,$v);return ['ok'=>true];}
 public function businessDates(){return ['Hotel'=>\App\Services\BusinessDate::date('Hotel'),'Restaurant'=>\App\Services\BusinessDate::date('Restaurant')];}
 public function closing(Request $q){
  $v=$q->validate(['date'=>'required|date|before_or_equal:today','department'=>'required|in:Hotel,Restaurant','counted_cash'=>'required|numeric|min:0|max:999999999','notes'=>'nullable|string|max:1000']);
  abort_unless($q->user()->role==='admin'||($q->user()->role==='frontdesk'&&$v['department']==='Hotel')||($q->user()->role==='restaurant'&&$v['department']==='Restaurant'),403);
  return DB::transaction(function()use($q,$v){
   $key='business_date_'.$v['department'];\App\Services\BusinessDate::date($v['department']);$setting=Setting::where('key',$key)->lockForUpdate()->first();
   $existing=DB::table('business_closings')->where('business_date',$v['date'])->where('department',$v['department'])->first();if($existing)return $existing;
   if($setting->value['date']!==$v['date'])Hotel::fail('Close the current open business date only.');
   if($v['department']==='Restaurant'&&RestaurantOrder::whereDate('created_at','<=',$v['date'])->where('status','Open')->exists())Hotel::fail('Resolve unpaid restaurant orders before closing.');
   if(\App\Models\PaymentCheckout::whereIn('status',['Creating','Pending','Review'])->when($v['department']==='Hotel',fn($b)=>$b->whereNull('restaurant_order_id'),fn($b)=>$b->whereNotNull('restaurant_order_id'))->exists())Hotel::fail('Reconcile pending or review-required payment checkouts before closing.');
   $payments=Payment::whereDate('created_at',$v['date'])->when($v['department']==='Hotel',fn($b)=>$b->whereNotNull('reservation_id'))->when($v['department']==='Restaurant',fn($b)=>$b->whereNotNull('restaurant_order_id'))->get();
   $expected=round($payments->where('method','Cash')->where('kind','Payment')->sum('amount')-$payments->where('method','Cash')->where('kind','Refund')->sum('amount'),2);
   if(abs($expected-$v['counted_cash'])>.005)Hotel::fail('Cash count does not reconcile. Expected PHP '.number_format($expected,2).'. Resolve the variance before closing.');
   $summary=['collections'=>$payments->where('kind','Payment')->sum('amount'),'refunds'=>$payments->where('kind','Refund')->sum('amount'),'expected_cash'=>$expected,'counted_cash'=>$v['counted_cash'],'room_charges'=>$v['department']==='Restaurant'?RestaurantOrder::whereDate('settled_at',$v['date'])->where('settlement','Room')->sum('amount'):0,'notes'=>$v['notes']??'','accommodation_posting'=>'Full accommodation is recorded at booking; do not repost nightly charges.'];
   $id=DB::table('business_closings')->insertGetId(['business_date'=>$v['date'],'department'=>$v['department'],'closed_by'=>$q->user()->id,'summary'=>json_encode($summary),'created_at'=>now(),'updated_at'=>now()]);
   $setting->update(['value'=>['date'=>\Carbon\Carbon::parse($v['date'])->addDay()->toDateString()]]);Hotel::audit('business-date.closed',(string)$id,$v);return ['id'=>$id,'summary'=>$summary,'next_date'=>$setting->value['date']];
  });
 }
}
